from pathlib import Path
import ast
import hashlib
import json
root=Path('.orchestra/tasks/V-1244/raw/approved/main/head')
guards={'ensure_hub_worker_allowed','ensure_spawn_allowed','validate_model_reason','ensure_dashboard_visible'}
result={}
for name in ('app/models.py','app/hub_pool.py','app/report_holds.py','app/routes/sessions.py',
             '.orchestra/pipelines/default/pipeline.yaml','.orchestra/pipelines/default/prompts/modules/model-routing.md'):
    current=Path(name).read_bytes(); expected=(root/name).read_bytes()
    assert current==expected,name
    result[name]={'byte_equal_to_main':True,'sha256':hashlib.sha256(current).hexdigest()}
for name in ('app/backend_hub.py','app/manager.py','app/session.py','app/mcp_stdio.py'):
    def calls(text):
        nodes=ast.parse(text)
        return sorted(ast.dump(n,include_attributes=False) for n in ast.walk(nodes)
                      if isinstance(n,ast.Call) and isinstance(n.func,ast.Name) and n.func.id in guards)
    before=calls((root/name).read_text()); after=calls(Path(name).read_text())
    assert before==after,name
    result[name]={'guard_calls_ast_equal_to_main':True,'guard_call_count':len(after)}
Path('.orchestra/tasks/V-1244/product-equivalence.json').write_text(json.dumps({
    'baseline_commit':'[скрыто]',
    'verification':'Exact unchanged owner bytes and normalized guard-call ASTs; runtime boundary tests recorded separately.',
    'preserved':result,
    'intentional_changes':['history-preserving ordinary Hub archival','existing-record archived marker and recovery/privacy barriers',
                           'non-destructive orphan observation','trusted conditional completion/merge instruction',
                           'fixture characterization aligned to approved default and actual session model'],
    'not_proven':'No live service/T3/provider/account activation was exercised.'},indent=2)+'\n')
print('Pinned-main owners and every guard call preserved')
PY
